from pathlib import Path
import json,csv,re,hashlib,collections,subprocess
R=Path(__file__).resolve().parents[1];O=R/'reports'
rows=json.loads((O/'math-checks.json').read_text());models=json.loads((O/'math-model-checks.json').read_text());manual=json.loads((O/'manual-math-checks.json').read_text());der=json.loads((R/'evidence/derivations.json').read_text())
num_ok=sum(x['numeric_pass'] and x['studium'].get('accepted') is True and x['studium'].get('correct') is True for x in rows)
dim=[x for x in rows if 'studium_dimensions' in x];dimok=sum(x['studium_dimensions'].get('accepted') is True and x['pint_dimensions_pass'] for x in dim)
symbolic=models['studium'][:-1]+[models['limit_retry']]
symok=sum(x.get('accepted') is True for x in symbolic)
derok=sum(x['check']['verification_status']=='DIMENSIONALLY_VERIFIED' for x in der)
assert num_ok==len(rows) and dimok==len(dim) and symok==len(symbolic) and derok==len(der)
(O/'Auditoria_matematica.md').write_text(f'''# Auditoría matemática\n\nFecha: 18 de octubre de 2026. Alcance: reproducción aritmética, álgebra/dimensiones de modelos seleccionados y revisión de hipótesis; no validación física experimental.\n\n## Comprobaciones completadas\n\n- {num_ok}/{len(rows)} sustituciones de los problemas y preguntas numéricas de simulacros contrastadas con SymPy a 30 cifras y aceptadas por Studium mediante reproducción del cálculo. Tolerancia de comparación 1e-10 relativa y 1e-12 absoluta.\n- {len(manual)} controles adicionales de los ejemplos numéricos del manual y taller, todos reproducidos con SymPy. Los ejemplos cualitativos se revisan conceptualmente, no se disfrazan como operaciones numéricas.\n- {dimok}/{len(dim)} controles dimensionales de expresiones de ejercicios, con Studium y contraste Pint.\n- {derok}/{len(der)} derivaciones registradas y comprobadas dimensionalmente: elongación, tamaño crítico, Paris m=3, relajación y sándwich.\n- {symok}/{len(symbolic)} identidades, derivadas o límites aceptados en la comprobación simbólica final, incluido límite exponencial tras declarar símbolos.\n- Cuatro integraciones independientes por Simpson adaptativo (P16, P17, P18 y S02.2), coincidentes con soluciones cerradas. Se registran estimaciones de error. SymPy contrasta también primitivas de potencia y logaritmo.\n\nLos 35 problemas y 13 preguntas numéricas de simulacros se almacenan en Studium con dos fuentes de contexto distintas; el resultado de su verificación nativa es two_witnesses. Esa denominación indica contexto de evidencias y reproducción, no revisión física por dos personas ni autoridad científica automática. Las cifras de los enunciados son originales y ficticias, no proceden de esas citas.\n\n## Errores de integración corregidos\n\nLos primeros controles de aritmética entera fueron rechazados por falta de contexto de ejercicio; se vincularon al paso exacto del problema registrado. Un primer enlace usó una sección distinta y fue rechazado; se corrigió la sección. El primer límite no declaró lambda y quedó FAILED; la repetición con símbolos declarados fue aceptada. Los registros conservan esos intentos, sin presentarlos como éxitos. Los primeros registros con dos fragmentos de una misma fuente no bastaban para dos fuentes; se sustituyeron por referencias de contexto distintas y se repitió el control.\n\n## Revisión física y unidades\n\nSe revisan explícitamente a frente a 2a, KI frente a KIC, máximo frente a rango, unidad de C de Paris, horas frente a segundos, temperatura absoluta, tensión de calibración de Larson–Miller y significado de los contadores. Las comprobaciones cubren todos los problemas mediante al menos una sustitución; no todas las igualdades del manual disponen de una prueba automática individual. Las unidades que no se automatizan se razonan en el desarrollo y sus modelos.\n\n## Limitaciones\n\nRepetir una operación no demuestra datos auténticos, ley constitutiva adecuada, espectro representativo, condición de ensayo, POD ni aprobación de un intervalo. No se calculan extensiones reales de vida. La revisión experta independiente sigue pendiente. Registro detallado: math-checks.json, manual-math-checks.json, math-model-checks.json, evidence/derivations.json y API final.\n''')
reg=[]
for x in rows:reg.append({'id':x['key'],'tipo':'Sustitución problema/simulacro','metodo':'SymPy + Studium','estado':'REPRODUCIDO','alcance':'Aritmética del ejercicio ficticio','evidencia':'math-checks.json'})
for x in manual:reg.append({'id':x['key'],'tipo':'Ejemplo manual','metodo':'SymPy','estado':'REPRODUCIDO','alcance':x['scope'],'evidencia':'manual-math-checks.json'})
for x in dim:reg.append({'id':x['key'],'tipo':'Dimensiones','metodo':'Studium + Pint','estado':'DIMENSIONALLY_VERIFIED','alcance':'Consistencia dimensional, no validez física','evidencia':'math-checks.json'})
for i,x in enumerate(symbolic,1):reg.append({'id':f'SYM-{i}','tipo':x['verification']['check'],'metodo':'Studium simbólico','estado':x['verification_status'],'alcance':'Identidad/derivada/límite con condiciones','evidencia':'math-model-checks.json'})
for x in der:reg.append({'id':x['record']['derivation']['id'],'tipo':'Derivación dimensional','metodo':'Studium','estado':x['check']['verification_status'],'alcance':x['name'],'evidencia':'evidence/derivations.json'})
for x in models['quadrature']:reg.append({'id':x['key'],'tipo':'Integral','metodo':'Simpson adaptativo frente a solución cerrada','estado':'COINCIDENTE' if x['pass'] else 'FALLO','alcance':'Integral del modelo, no adecuación de Paris','evidencia':'math-model-checks.json'})
with (O/'Registro_verificaciones.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(reg[0]));w.writeheader();w.writerows(reg)
# Ampliar inventario a igualdades en línea y apéndice de fórmulas, sin afirmar prueba automática de todas.
path=O/'Inventario_ecuaciones.csv';equations=list(csv.DictReader(path.open()))
known={x['latex'] for x in equations}
for n in range(1,26):
 s=(R/'content'/f'c{n:02d}.tex').read_text()+(R/'content'/f'e{n:02d}.tex').read_text()
 for j,eq in enumerate(re.findall(r'\$([^$]+)\$',s),1):
  if '=' not in eq or eq in known:continue
  equations.append({'id':f'IN-{n:02d}-{j:03d}','capitulo':n,'latex':eq,'alcance':'Igualdad o condición en línea; ver contexto e hipótesis del capítulo','verificacion':'Inventariada; controles automáticos concretos identificados en registros'});known.add(eq)
s=(R/'content/appendices.tex').read_text()
for j,m in enumerate(re.finditer(r'\\begin\{align\*\}(.*?)\\end\{align\*\}|\\\[(.*?)\\\]',s,re.S),1):
 equations.append({'id':f'AP-A-{j}','capitulo':'A','latex':(m[1] or m[2]).strip(),'alcance':'Hoja de fórmulas; remite a hipótesis de capítulos','verificacion':'No prueba independiente por aparecer en apéndice'})
with path.open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(equations[0]));w.writeheader();w.writerows(equations)
# Extender registro de norma a los vuelos incluidos tras recuperar guía.
path=O/'Registro_normativo.json';legal=json.loads(path.read_text());src=next(x for x in json.loads((R/'evidence/fuentes-publicas.json').read_text()) if x['key']=='EU748')
legal.append({'id':'N36','capitulo':16,'afirmacion':'Permiso y condiciones de vuelo tienen objeto, fines y rutas de aprobación/emisión específicos.','autoridad':'Unión Europea','fuente':'EU748','disposicion':'21.A.701; .708; .710; .711','fecha_consulta':'2026-10-18','ambito':'Aeronave y finalidad dentro de subparte P; no permiso general de taller Parte 145','estado':'CONTRASTE DOCUMENTAL','observaciones':'No se prescribe perfil de ensayo ni autorización. M.A.301(i), del 1321/2014, contempla vuelos de comprobación cuando sean necesarios.','url':src['url'],'version':src['title'],'sha256':src['sha256']})
path.write_text(json.dumps(legal,ensure_ascii=False,indent=2))
with (O/'Registro_normativo.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(legal[0]));w.writeheader();w.writerows(legal)
p=O/'Auditoria_normativa.md';s=p.read_text().replace('35 fichas','36 fichas');s+='\n## Ampliación tras contrastar la guía\n\nSe añadió la ficha N36 para permisos y condiciones de vuelo (Parte 21 subparte P), con contraste del texto oficial. La guía 2026–2027 se recuperó íntegra y se incorporó a la bibliografía; su evaluación global es 75%/25%. Los datos de presentación se conservan atribuidos a esa fuente docente.\n';p.write_text(s)
summary={'numeric_exercises':num_ok,'numeric_manual':len(manual),'dimensions_exercises':dimok,'dimensions_derivations':derok,'symbolic_checks':symok,'quadratures':len(models['quadrature']),'equation_inventory_entries':len(equations),'legal_entries':len(legal),'release':'EN REVISIÓN; no RELEASED','native_book_review':json.loads((O/'studium_book_review.json').read_text())['status']}
(O/'final-check-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
print(json.dumps(summary,ensure_ascii=False))
